// Productive on an API token and the organization's id: every operation of Productive's API (their OpenAPI spec).
// actions.json is generated by `bun scripts/openapi-actions.ts productive`. The API is JSON:API: the generator flattens
// each body into plain fields, and run() here builds {"data": {"type", "attributes", "relationships"}} back. Tasks,
// deals, invoices and the rest start automations by webhook (triggers.ts); comments and docs are polled (polls/).
import type { OwnAction, OwnApp } from "../index";
import { call, type Send, specActions } from "../openapi";
import { api, parseKey } from "./client";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

type Meta = { type?: string; rels?: Record<string, [name: string, type: string, many: boolean]>; bulk?: boolean };
type Generated = { name: string; send: Send; jsonapi?: Meta };

// filter: {"project_id": "1", "due_date": {"lt": "…"}} → filter[project_id]=1&filter[due_date][lt]=…; lists comma separated
function flatQuery(key: string, v: unknown, out: Record<string, string>) {
  if (v === undefined) return;
  if (Array.isArray(v)) out[key] = v.join(",");
  else if (v && typeof v === "object") for (const [k, x] of Object.entries(v)) flatQuery(`${key}[${k}]`, x, out);
  else out[key] = String(v);
}

// a relationship given as an id (or the whole {type, id} where our guess at the type is wrong)
const link = (type: string, v: unknown) => (v && typeof v === "object" ? v : { type, id: String(v) });

export function request(a: Generated, input: Record<string, unknown>) {
  const { send, jsonapi } = a;
  const inPath = [...send.path.matchAll(/\{(\w+)\}/g)].map((m) => m[1]!);
  const values: Record<string, unknown> = Object.fromEntries(inPath.map((k) => [k, input[k]]));
  const query: Record<string, string> = {};
  for (const k of send.query) flatQuery(k, input[k], query);
  let body: unknown;
  const fields = send.body?.kind === "fields" ? send.body.fields : [];
  if (jsonapi?.type) {
    const attributes: Record<string, unknown> = {};
    const relationships: Record<string, unknown> = {};
    for (const [field, k] of fields) {
      const v = input[field];
      if (v === undefined) continue;
      const rel = jsonapi.rels?.[k];
      if (!rel) attributes[k] = v;
      else relationships[rel[0]] = { data: rel[2] ? [v].flat().map((x) => link(rel[1], x)) : v === null ? null : link(rel[1], v) };
    }
    const id = send.method === "PATCH" && input.id !== undefined ? { id: String(input.id) } : {};
    body = { data: { type: jsonapi.type, ...id, attributes, ...(Object.keys(relationships).length && { relationships }) } };
  } else if (fields.some(([f]) => input[f] !== undefined)) body = Object.fromEntries(fields.flatMap(([f, k]) => (input[f] === undefined ? [] : [[k, input[f]]])));
  return {
    send: { method: send.method, path: send.path, query: Object.keys(query), headers: [], ...(body !== undefined && { body: { kind: "whole" as const, field: "__body" } }) },
    input: { ...values, ...query, __body: body, __bulk: jsonapi?.bulk },
  };
}

const file = new URL("./actions.json", import.meta.url);
const actions = await specActions(file, api);
for (const a of (await Bun.file(file).json()).actions as Generated[]) {
  actions[a.name]!.run = (input: Record<string, unknown>, key: string) => {
    const r = request(a, input);
    return call(api, key, r.send, r.input);
  };
}

const ME: Send = { method: "GET", path: "/api/v2/organizations/{id}", query: [], headers: [] };

export const productive: OwnApp = {
  app: "productive",
  name: "Productive",
  logo: "/logos/productive.svg",
  keyField: {
    label: "Organization ID and API token",
    help: "In Productive open Settings → API integrations and press Generate new token (give it full access, not read-only). The same page shows your Organization ID. Emplio can then do whatever that token can.",
    placeholder: "12345:your-api-token",
    sep: ":",
    parts: [{label:"Organization ID",placeholder:"12345"},{label:"API token",secret:true,placeholder:"your-api-token"}],
  },
  async check(key) {
    const { org } = parseKey(key);
    const { data } = (await call(api, key, ME, { id: org })) as { data: { id: string; attributes?: { name?: string } } };
    return data.attributes?.name || data.id;
  },
  push: {
    events,
    triggers,
    start: (key, connection, event, config) => watch(key, connection, event, config),
    stop: (key, id) => unwatch(key, id),
    receive: (delivery, key) => receive(delivery, key),
    wanted,
  },
  actions: actions as Record<string, OwnAction>,
};
